    // Implement: ignore case
    return false
}
for w in ["level", "swift", "Racecar"] {
    // Print "word: true/false"
}

solution:
func isPalindrome(_ s: String) -> Bool {
    let t = s.lowercased()
    return t == String(t.reversed())
}
for w in ["level", "swift", "Racecar"] {
    print("\(w): \(isPalindrome(w))")
}

