    // Implement recursively
    return 0
}
// Print "5! = ..." and "fib(10) = ..."

solution:
func factorial(_ n: Int) -> Int {
    n <= 1 ? 1 : n * factorial(n - 1)
}
func fib(_ n: Int) -> Int {
    n < 2 ? n : fib(n - 1) + fib(n - 2)
}
print("5! = \(factorial(5))")
print("fib(10) = \(fib(10))")

