struct Stack<T> {
    // Store items, add push, pop and peek
}
var s = Stack<Int>()
s.push(1); s.push(2); s.push(3)
// Print peek, then the popped value, then the count

solution:
struct Stack<T> {
    private var items: [T] = []
    var count: Int { items.count }
    var peek: T? { items.last }
    mutating func push(_ x: T) { items.append(x) }
    mutating func pop() -> T? { items.popLast() }
}
var s = Stack<Int>()
s.push(1); s.push(2); s.push(3)
print(s.peek ?? -1)
print(s.pop() ?? -1)
print(s.count)

