@propertyWrapper
struct Clamped {
    var wrappedValue: Int // clamp to 0...100 on set
}
struct Player {
    @Clamped var health = 50
}
var p = Player()
// Set health to 150, print; set to -20, print

solution:
@propertyWrapper
struct Clamped {
    private var value: Int
    var wrappedValue: Int {
        get { value }
        set { value = min(max(newValue, 0), 100) }
    }
    init(wrappedValue: Int) { value = min(max(wrappedValue, 0), 100) }
}
struct Player {
    @Clamped var health = 50
}
var p = Player()
p.health = 150
print(p.health)
p.health = -20
print(p.health)

