import Foundation

struct Person: Codable {
    let name: String
    let age: Int
}
let p = Person(name: "Ana", age: 30)
// Encode with .sortedKeys and print the JSON string
// Decode it back and print the name

solution:
import Foundation

struct Person: Codable {
    let name: String
    let age: Int
}
let p = Person(name: "Ana", age: 30)
let encoder = JSONEncoder()
encoder.outputFormatting = .sortedKeys
let data = try! encoder.encode(p)
print(String(data: data, encoding: .utf8)!)
let back = try! JSONDecoder().decode(Person.self, from: data)
print(back.name)

